"""Build a self-contained local ESG retrieval workbench."""
from pathlib import Path
import csv
import json
import sys

ROOT = Path(__file__).resolve().parents[1]
CLAUSE_DATA = ROOT / "data" / "clauses"
DICTIONARY_DATA = ROOT / "data" / "dictionaries"
FIXTURE = ROOT / "data" / "fixtures" / "yuexiu_2024_pages_62_67"
OUT = ROOT / "outputs"

def read_csv(path):
    with path.open(encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))

clauses = read_csv(CLAUSE_DATA / "standard_clauses_sample.csv")
clauses += read_csv(CLAUSE_DATA / "hkex_climate_clauses_sample.csv")
clauses += read_csv(CLAUSE_DATA / "cross_framework_core_clauses_sample.csv")
aliases = read_csv(DICTIONARY_DATA / "synonyms_sample.csv")
alias_path = DICTIONARY_DATA / "official_report_aliases_sample.csv"
if alias_path.exists():
    aliases += read_csv(alias_path)
document = json.loads((FIXTURE / "document_ir.json").read_text(encoding="utf-8"))
reviewed = read_csv(OUT / "evidence_reviewed_candidates.csv")
lexical = read_csv(OUT / "document_ir_retrieval_candidates.csv")
vector = read_csv(OUT / "document_ir_vector_candidates.csv")
if "--blank" in sys.argv:
    document = {"metadata": {"run_id": "未载入 Document IR"}, "pages": []}
    reviewed = []
    lexical = []
    vector = []
payload = json.dumps({"clauses": clauses, "aliases": aliases, "document": document, "reviewed": reviewed, "lexical": lexical, "vector": vector}, ensure_ascii=False).replace("</", "<\\/")

html_text = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ESG Retrieval Workbench</title>
<style>
:root{--ink:#17352d;--muted:#62776f;--line:#d5e4de;--green:#087f5b;--pale:#e6f5ee;--bg:#f4f8f6;--amber:#a06200;--red:#a63d35}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Segoe UI,Microsoft YaHei,sans-serif}.top{background:#103f33;color:#fff;padding:20px 28px;display:flex;align-items:center;justify-content:space-between}.top h1{font-size:21px;margin:0 0 5px}.top p{margin:0;color:#c9e4d9;font-size:13px}.top button{background:#fff;color:var(--green);border:0;border-radius:7px;padding:10px 14px;font-weight:700;cursor:pointer}.layout{display:grid;grid-template-columns:235px 1fr;min-height:calc(100vh - 84px)}.side{background:#fff;border-right:1px solid var(--line);padding:18px 12px}.side .step{padding:12px 14px;border-radius:8px;margin:5px 0;cursor:pointer;font-size:14px}.side .step:hover,.side .step.active{background:var(--pale);color:var(--green);font-weight:700}.side small{display:block;color:var(--muted);margin:18px 12px 5px}.main{padding:24px 28px;max-width:1500px;width:100%}.view{display:none}.view.active{display:block}.title{display:flex;align-items:end;justify-content:space-between;gap:15px}.title h2{margin:0 0 4px;font-size:22px}.muted{color:var(--muted);font-size:13px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin:20px 0}.card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:15px}.card b{font-size:25px;color:var(--green);display:block;margin-bottom:5px}.panel{background:#fff;border:1px solid var(--line);border-radius:10px;padding:17px;margin:16px 0}.panel h3{margin:0 0 12px;font-size:16px}.flow{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.flow span{background:var(--pale);border:1px solid #a5d5c2;padding:9px 11px;border-radius:7px;font-size:13px}.flow i{font-style:normal;color:var(--green);font-weight:700}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin:10px 0}.toolbar input,.toolbar select{padding:9px;border:1px solid var(--line);border-radius:6px;background:#fff}.btn{border:1px solid var(--green);background:var(--green);color:#fff;border-radius:6px;padding:9px 13px;cursor:pointer;font-weight:600}.btn.secondary{background:#fff;color:var(--green)}table{border-collapse:collapse;width:100%;font-size:12px;background:#fff}th,td{border:1px solid var(--line);padding:8px;text-align:left;vertical-align:top}th{background:#e9f5ef;position:sticky;top:0;z-index:1}td.snip{max-width:460px;line-height:1.5}.keep_candidate{color:var(--green);font-weight:700}.uncertain{color:var(--amber);font-weight:700}.reject_candidate{color:var(--red);font-weight:700}.tag{display:inline-block;background:#edf4f1;border-radius:12px;padding:3px 8px;margin:2px;font-size:11px}.pagebox{white-space:pre-wrap;line-height:1.65;background:#fcfefd;border:1px solid var(--line);padding:15px;border-radius:7px;max-height:560px;overflow:auto}.source{font-size:12px;color:var(--muted);margin-top:8px}.notice{background:#fff8e4;border-left:4px solid #d39a31;padding:11px 14px;font-size:13px;line-height:1.6}.ok{color:var(--green)}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line);display:flex;overflow:auto}.side small{display:none}.side .step{white-space:nowrap}.grid2{grid-template-columns:1fr}}
</style><style>
/* visual refinement: restrained technical workbench treatment */
body{background:linear-gradient(135deg,#eef7f3 0%,#f7faf9 48%,#edf4f2 100%);letter-spacing:.01em}
.top{background:linear-gradient(120deg,#0a3029 0%,#0d5142 56%,#087f5b 100%);box-shadow:0 5px 22px #0b4a3a26;padding:22px 30px}
.top h1{letter-spacing:.03em}.top p{font-size:12px;opacity:.9}.top button{box-shadow:0 4px 12px #06291f55;transition:transform .16s,box-shadow .16s}.top button:hover{transform:translateY(-1px);box-shadow:0 6px 16px #06291f66}
.side{background:rgba(255,255,255,.84);backdrop-filter:blur(8px);box-shadow:5px 0 22px #1653420d;padding:22px 14px}.side .step{border-left:3px solid transparent;transition:background .16s,color .16s,border-color .16s;padding-left:16px}.side .step:hover{background:#eaf7f1}.side .step.active{border-left-color:#16a77b;background:linear-gradient(90deg,#e3f5ed,#f6fbf8);color:#076c4d}
.main{padding:30px 34px}.title h2{letter-spacing:.01em}.cards{gap:16px}.card{border:1px solid #d7e9e1;box-shadow:0 8px 22px #164b3b0b;transition:transform .16s,box-shadow .16s}.card:hover{transform:translateY(-2px);box-shadow:0 12px 26px #164b3b18}.card b{font-variant-numeric:tabular-nums}
.panel{border:1px solid #d7e8e1;box-shadow:0 7px 20px #164b3b08}.panel h3{color:#194d3f;letter-spacing:.02em}.flow span{box-shadow:0 3px 8px #0c614812}.flow i{padding:0 2px}
.toolbar input:focus,.toolbar select:focus,.locator:focus,.notes:focus{outline:2px solid #8ad7bc;outline-offset:1px;border-color:#31a983}
.btn{box-shadow:0 4px 10px #087f5b22;transition:transform .16s,box-shadow .16s}.btn:hover{transform:translateY(-1px);box-shadow:0 7px 15px #087f5b33}.btn.secondary{box-shadow:none}
table{border-radius:8px;overflow:hidden}th{background:linear-gradient(180deg,#e6f5ee,#dff1e9);color:#164a3c;letter-spacing:.02em}tr:nth-child(even) td{background:#fbfdfc}tr:hover td{background:#f0faf5}
.pagebox{box-shadow:inset 0 0 0 1px #fff,0 4px 14px #164b3b0b}.notice{box-shadow:0 3px 10px #a0620012}
</style></head><body>
<div class="top"><div><h1>ESG Retrieval Workbench</h1><p>Document IR → 条款候选 → Evidence 复核（本地可操作原型）</p></div><button id="uploadBtn">载入新的 Document IR JSON</button><input id="fileInput" type="file" accept=".json" hidden></div>
<div class="layout"><nav class="side"><small>工作流</small><div class="step active" data-view="home">① 工作台总览</div><div class="step" data-view="document">② Document IR 浏览器</div><div class="step" data-view="clauses">③ 官方条款库</div><div class="step" data-view="aliases">④ 同义词词典</div><div class="step" data-view="retrieve">⑤ 运行候选召回</div><div class="step" data-view="review">⑥ Evidence 复核队列</div><small>当前材料</small><div id="runLabel" class="muted" style="padding:0 12px;line-height:1.5"></div></nav><main class="main">
<section id="home" class="view active"><div class="title"><div><h2>工作台总览</h2><div class="muted">可以查看输入、规则、召回结果，也可以载入新的 Document IR 重新运行。</div></div><button class="btn" onclick="go('retrieve')">开始一次召回</button></div><div class="cards"><div class="card"><b id="statPages">—</b>Document IR 页面</div><div class="card"><b id="statClauses">—</b>官方条款</div><div class="card"><b id="statAliases">—</b>同义词/报告表达</div><div class="card"><b id="statCandidates">—</b>当前候选</div><div class="card"><b id="statKeep">—</b>已保留候选</div><div class="card"><b id="statUncertain">—</b>待复核</div></div><div class="panel"><h3>实际处理链路</h3><div class="flow"><span>输入 Document IR</span><i>→</i><span>读取官方条款</span><i>→</i><span>展开同义表达</span><i>→</i><span>关键词/向量候选</span><i>→</i><span>人工定位原文</span><i>→</i><span>形成 Evidence</span></div></div><div class="panel"><h3>当前输入</h3><p id="inputSummary" class="muted"></p><div class="notice"><b>判断边界：</b>候选不是合规结论。最终 Evidence 必须回到原始 PDF、表格或图，记录具体位置。</div></div></section>
<section id="document" class="view"><div class="title"><div><h2>Document IR 浏览器</h2><div class="muted">查看结构化页面文本；顶部按钮可以载入新的 JSON。</div></div></div><div class="toolbar"><select id="pageSelect"></select></div><div class="panel"><div id="pageText" class="pagebox"></div><div id="pageSource" class="source"></div></div></section>
<section id="clauses" class="view"><div class="title"><div><h2>官方条款库</h2><div class="muted">查看框架、版本、定位和官方来源。</div></div></div><div class="toolbar"><input id="clauseSearch" placeholder="搜索标题、框架、主题"><select id="frameworkFilter"><option value="">全部框架</option></select></div><div class="panel" style="overflow:auto;max-height:650px"><table><thead><tr><th>ID</th><th>框架/标准</th><th>标题</th><th>主题</th><th>官方定位</th><th>来源</th></tr></thead><tbody id="clauseTable"></tbody></table></div></section>
<section id="aliases" class="view"><div class="title"><div><h2>同义词与报告表达</h2><div class="muted">条款概念与报告实际表达的连接层。</div></div></div><div class="toolbar"><input id="aliasSearch" placeholder="搜索概念或表达"></div><div class="panel" style="overflow:auto;max-height:650px"><table><thead><tr><th>概念</th><th>表达</th><th>语言</th><th>来源</th></tr></thead><tbody id="aliasTable"></tbody></table></div></section>
<section id="retrieve" class="view"><div class="title"><div><h2>运行候选召回</h2><div class="muted">对当前 Document IR 逐页扫描条款标题、主题和同义表达。</div></div><button class="btn" id="runBtn">运行一次召回</button></div><div class="panel"><div class="notice">浏览器版本使用可解释的关键词/同义表达评分。历史 TF-IDF 结果保留在输出文件中，便于比较。</div><div id="runStatus" class="muted" style="margin-top:12px"></div></div><div class="panel" style="overflow:auto;max-height:600px"><table><thead><tr><th>页码</th><th>条款</th><th>标题</th><th>得分</th><th>命中表达</th><th>操作</th></tr></thead><tbody id="resultTable"></tbody></table></div></section>
<section id="review" class="view"><div class="title"><div><h2>Evidence 复核队列</h2><div class="muted">逐条选择保留、待确认或排除，并记录页/段落/表格/图位置。</div></div><button class="btn" id="exportBtn">导出当前复核 CSV</button></div><div class="panel"><div class="toolbar"><select id="reviewFilter"><option value="">全部</option><option value="keep_candidate">保留候选</option><option value="uncertain">待确认</option><option value="reject_candidate">排除</option></select></div><div style="overflow:auto;max-height:650px"><table><thead><tr><th>页码</th><th>条款</th><th>决定</th><th>来源片段</th><th>证据定位</th><th>备注</th></tr></thead><tbody id="reviewTable"></tbody></table></div></div></section>
</main></div>
<script>const DATA=__PAYLOAD__;let currentDoc=DATA.document, runtimeResults=[], reviewRows=DATA.reviewed.slice();const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));function go(v){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v));document.querySelectorAll('.step').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='document')renderPage();if(v==='clauses')renderClauses();if(v==='aliases')renderAliases();if(v==='review')renderReview()}document.querySelectorAll('.step').forEach(x=>x.onclick=()=>go(x.dataset.view));function init(){$('statPages').textContent=currentDoc.pages.length;$('statClauses').textContent=DATA.clauses.length;$('statAliases').textContent=DATA.aliases.length;$('statCandidates').textContent=reviewRows.length;$('statKeep').textContent=reviewRows.filter(x=>x.manual_decision==='keep_candidate').length;$('statUncertain').textContent=reviewRows.filter(x=>x.manual_decision==='uncertain').length;$('runLabel').textContent=(currentDoc.metadata?.run_id||'未命名运行')+'\n'+currentDoc.pages.length+' 页';$('inputSummary').textContent='当前运行：'+(currentDoc.metadata?.run_id||'未命名')+'；页面覆盖：'+currentDoc.pages.length+' 页。条款库和同义词已嵌入，可直接浏览。';const fs=[...new Set(DATA.clauses.map(x=>x.framework))];$('frameworkFilter').innerHTML='<option value="">全部框架</option>'+fs.map(x=>`<option>${esc(x)}</option>`).join('');$('pageSelect').innerHTML=currentDoc.pages.map((p,i)=>`<option value="${i}">印刷页 ${esc(p.printed_page_label||i+1)}</option>`).join('');$('pageSelect').onchange=renderPage;renderPage();renderClauses();renderAliases();renderReview()}function renderPage(){const i=+$('pageSelect').value||0,p=currentDoc.pages[i];if(!p)return;$('pageText').textContent=p.text||'(该页没有规范文本)';$('pageSource').textContent='page_id: '+(p.page_id||'')+' | page_index: '+(p.page_index??'')+' | printed_page_label: '+(p.printed_page_label||'')}function renderClauses(){const q=($('clauseSearch').value||'').toLowerCase(),f=$('frameworkFilter').value;const out=DATA.clauses.filter(x=>(!f||x.framework===f)&&JSON.stringify(x).toLowerCase().includes(q));$('clauseTable').innerHTML=out.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.framework)}<br>${esc(x.standard_id)}<br><span class="tag">v${esc(x.version)}</span></td><td>${esc(x.title)}</td><td>${esc(x.topic)} / ${esc(x.subtopic)}<br>${esc(x.metric_type)}</td><td>${esc(x.source_locator)}</td><td><a href="${esc(x.source_url)}" target="_blank">官方来源</a></td></tr>`).join('')}function renderAliases(){const q=($('aliasSearch').value||'').toLowerCase();const out=DATA.aliases.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('aliasTable').innerHTML=out.map(x=>`<tr><td>${esc(x.concept_id)}</td><td>${esc(x.alias)}</td><td>${esc(x.language||'')}</td><td>${esc(x.source_url||x.source_type||'')}</td></tr>`).join('')}function run(){const aliases={};DATA.aliases.forEach(a=>(aliases[a.concept_id]??=[]).push(a.alias));const results=[];currentDoc.pages.forEach(p=>{const text=(p.text||'').toLowerCase();DATA.clauses.forEach(c=>{let score=0,hit=[];const title=(c.title||'').toLowerCase();if(title&&text.includes(title)){score+=5;hit.push(c.title)}(aliases[c.metric_type]||[]).forEach(a=>{if(a&&text.includes(a.toLowerCase())){score+=3;hit.push(a)}});if(score)results.push({page:p,c,score,hit:[...new Set(hit)]})})});results.sort((a,b)=>b.score-a.score||String(a.page.printed_page_label).localeCompare(String(b.page.printed_page_label)));runtimeResults=results;reviewRows=results.map(x=>({printed_page_label:x.page.printed_page_label,candidate_clause_id:x.c.id,candidate_title:x.c.title,manual_decision:'uncertain',evidence_snippet:x.hit.join(' | '),evidence_locator:'',review_notes:'',retrieved_by:'browser_lexical'}));$('statCandidates').textContent=reviewRows.length;$('statKeep').textContent='0';$('statUncertain').textContent=reviewRows.length;$('runStatus').innerHTML='<span class="ok">已完成一次浏览器关键词/同义表达召回：</span> '+results.length+' 条候选。';renderResults();renderReview()}function renderResults(){$('resultTable').innerHTML=runtimeResults.map(x=>`<tr><td>${esc(x.page.printed_page_label)}</td><td>${esc(x.c.id)}</td><td>${esc(x.c.title)}</td><td>${x.score.toFixed(1)}</td><td>${x.hit.map(esc).join(' | ')}</td><td><button class="btn secondary" onclick="go('review')">进入复核</button></td></tr>`).join('')}function renderReview(){const f=$('reviewFilter').value||'',out=reviewRows.filter(x=>!f||x.manual_decision===f);$('reviewTable').innerHTML=out.map((x,i)=>`<tr><td>${esc(x.printed_page_label)}</td><td>${esc(x.candidate_clause_id)}<br>${esc(x.candidate_title)}</td><td><select data-i="${i}" class="decision"><option value="keep_candidate" ${x.manual_decision==='keep_candidate'?'selected':''}>保留候选</option><option value="uncertain" ${x.manual_decision==='uncertain'?'selected':''}>待确认</option><option value="reject_candidate" ${x.manual_decision==='reject_candidate'?'selected':''}>排除</option></select></td><td>${esc(x.evidence_snippet||'')}</td><td><input class="locator" data-i="${i}" value="${esc(x.evidence_locator||'')}" placeholder="页/段落/表格/图"></td><td><input class="notes" data-i="${i}" value="${esc(x.review_notes||'')}" placeholder="审核说明"></td></tr>`).join('');document.querySelectorAll('.decision').forEach(e=>e.onchange=()=>{reviewRows[e.dataset.i].manual_decision=e.value;updateStats()});document.querySelectorAll('.locator').forEach(e=>e.onchange=()=>reviewRows[e.dataset.i].evidence_locator=e.value);document.querySelectorAll('.notes').forEach(e=>e.onchange=()=>reviewRows[e.dataset.i].review_notes=e.value)}function updateStats(){$('statCandidates').textContent=reviewRows.length;$('statKeep').textContent=reviewRows.filter(x=>x.manual_decision==='keep_candidate').length;$('statUncertain').textContent=reviewRows.filter(x=>x.manual_decision==='uncertain').length}function csv(){const fields=['printed_page_label','candidate_clause_id','candidate_title','manual_decision','evidence_snippet','evidence_locator','review_notes','retrieved_by'];const body=[fields.join(','),...reviewRows.map(r=>fields.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([new TextEncoder().encode('\ufeff'+body)],{type:'text/csv;charset=utf-8'}));a.download='evidence_review_export.csv';a.click()}$('runBtn').onclick=run;$('exportBtn').onclick=csv;$('clauseSearch').oninput=renderClauses;$('frameworkFilter').onchange=renderClauses;$('aliasSearch').oninput=renderAliases;$('reviewFilter').onchange=renderReview;$('uploadBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{currentDoc=JSON.parse(r.result);init();go('document')}catch(err){alert('JSON 无法读取：'+err.message)}};r.readAsText(f,'utf-8')};init();</script></body></html>'''
html_text = html_text.replace('__PAYLOAD__', payload)
filename = 'esg_retrieval_workbench_blank.html' if '--blank' in sys.argv else 'esg_retrieval_workbench.html'
(OUT / filename).write_text(html_text, encoding='utf-8')
print(OUT / filename)
